INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(188,'Art. 485. O contribuinte que realizar incorporação imobiliária submetida ao patrimônio de afetação, nos termos dos arts. 31-A a 31-E da Lei nº 4.591, de 16 de dezembro de 1964, que tenha realizado o pedido de opção pelo regime específico instituído pelo art. 1º e tenha o pedido efetivado nos termos do art. 2º, ambos da Lei nº 10.931 de 2 de agosto de 2004, antes de 1º de janeiro de 2029, pode optar pelo recolhimento de IBS e de CBS, da seguinte forma: '||X'0a'
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(189,'Art. 486. O contribuinte que realizar alienação de imóvel decorrente de parcelamento do solo, que tenha o pedido de registro do parcelamento, nos termos da Lei nº 6.766, de 19 de dezembro de 1979, efetivado antes de 1º de janeiro de 2029, pode optar pelo recolhimento de IBS e de CBS com base na receita bruta recebida. '||X'0a'
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(190,'Art. 12. A base de cálculo do IBS e da CBS é o valor da operação, salvo disposição em contrário prevista nesta Lei Complementar.'||X'0a'
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(191,'Art. 66. Não constituem fatos geradores do IBS e da CBS sobre a importação os bens materiais:'||X'0a'
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(192,'Art. 107. O Regime Tributário para Incentivo à Atividade Econômica Naval – Renaval permite aos beneficiários previamente habilitados suspensão do pagamento de IBS e CBS:'||X'0a'
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(193,'Art. 107. O Regime Tributário para Incentivo à Atividade Econômica Naval – Renaval permite aos beneficiários previamente habilitados suspensão do pagamento de IBS e CBS:'||X'0a'
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(194,'Art. 47. O contribuinte sujeito ao regime regular poderá apropriar créditos do IBS e da CBS quando ocorrer a extinção por qualquer das modalidades previstas no art. 27 dos débitos relativos às operações em que seja adquirente, excetuadas exclusivamente aquelas consideradas de uso ou consumo pessoal, nos termos do art. 57 desta Lei Complementar, e as demais hipóteses previstas nesta Lei Complementar.'||X'0a'
